/*
** tests/bench_lex_gate.c -- B5: base lexing throughput with and without
** an extension lexical rule loaded.
**
** PostgreSQL's scanner (tests/pg_scan_core.lex) is generated by lime -X
** twice: as is (Core*), and with `%runtime_rules.` added (Gate*, see
** tests/meson.build).  Variants, all lexing the same files with the same
** PG-free actions:
**
**   plain    Core scanner, no hook compiled in (the B4 baseline)
**   twin     the plain scanner generated again under another prefix:
**            different code, same tables -- the code-layout noise floor
**   none     Gate scanner, no hook installed (xrules == NULL)
**   cold     Gate scanner + lime_lexicon_ext_match, extension rule whose
**            leading byte never occurs in the corpus (U+00A7 0xC2 0xA7...)
**   hot      same, the extension rule starts with '#' (474 in the
**            corpus, and in PG '#' is an operator char), so the gate
**            fires and the extension DFA runs on every '#'
**
** First every variant's token stream (kind, start, end) must equal
** plain's: an extension rule that never matches the base corpus must
** not change base lexing.  Then CPU time per byte, median of N reps
** (BENCH_REPS, default 0 = check only), variants rotated each rep.
*/
#define _POSIX_C_SOURCE 200809L
#include "extension.h"
#include "lime_lexer.h"
#include "parser.h"
#include "snapshot.h"
#include "pg_scan_core_act.h"
#include "pg_scan_gate_lex.h"
#include "pg_scan_twin_lex.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "lime_time.h"

extern int lime_compile_grammar_in_process(const char *, size_t, ParserSnapshot **, char **);

static char *slurp(const char *path, size_t *len) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *b = malloc((size_t)n + 1);
    if (b && fread(b, 1, (size_t)n, f) != (size_t)n) {
        free(b);
        b = NULL;
    }
    if (b) b[n] = 0;
    fclose(f);
    *len = (size_t)n;
    return b;
}

static unsigned long long g_hash;
static size_t g_ntok;
static void hsink(void *u, int kind, size_t s, size_t e) {
    (void)u;
    unsigned long long x = ((unsigned long long)kind << 48) ^ ((unsigned long long)s << 24) ^ e;
    g_hash = (g_hash ^ x) * 1099511628211ull;
    g_ntok++;
}
/* extension tokens arrive through the emit callback, not the action */
static void ext_emit(void *user, int rule, const char *t, size_t n) {
    PgscCtx *cx = user;
    hsink(NULL, 1000 + rule, (size_t)(t - cx->base), (size_t)(t - cx->base) + n);
}


enum { V_PLAIN, V_TWIN, V_NONE, V_COLD, V_HOT, NV };
static const char *vname[NV] = { "plain (no hook compiled)", "twin of plain (layout noise)",
                                 "gate scanner, no ext", "ext rule, lead byte unused",
                                 "ext rule on '#' (hot)" };

static void run(int v, const LimeLexicon *cold, const LimeLexicon *hot, char **bufs, size_t *lens,
                int nb) {
    for (int a = 0; a < nb; a++) {
        if (!bufs[a]) continue;
        PgscCtx cx = { 0 };
        cx.sink = hsink;
        cx.base = bufs[a];
        if (v == V_PLAIN) {
            CoreLexer *l = CoreLexAlloc(malloc);
            CoreLexFeedBytes(l, bufs[a], lens[a], NULL, &cx);
            CoreLexFree(l, free);
        } else if (v == V_TWIN) {
            TwinLexer *l = TwinLexAlloc(malloc);
            TwinLexFeedBytes(l, bufs[a], lens[a], NULL, &cx);
            TwinLexFree(l, free);
        } else {
            GateLexer *l = GateLexAlloc(malloc);
            if (v == V_COLD)
                GateLexSetRuntimeRules(l, lime_lexicon_ext_match, lime_lexicon_ext_resolve, cold);
            if (v == V_HOT)
                GateLexSetRuntimeRules(l, lime_lexicon_ext_match, lime_lexicon_ext_resolve, hot);
            GateLexFeedBytes(l, bufs[a], lens[a], ext_emit, &cx);
            GateLexFree(l, free);
        }
    }
}

static double cpu_ns(void) {
#if defined(CLOCK_PROCESS_CPUTIME_ID) && !defined(_WIN32)
    struct timespec t;
    clock_gettime(CLOCK_PROCESS_CPUTIME_ID, &t);
    return (double)t.tv_sec * 1e9 + (double)t.tv_nsec;
#else
    return (double)lime_now_ns();  /* Windows: wall clock; the meson test only checks agreement */
#endif
}
static int dcmp(const void *a, const void *b) {
    double x = *(const double *)a, y = *(const double *)b;
    return x < y ? -1 : x > y;
}
static void report(const char *what, double *v, int n, const char *unit) {
    qsort(v, (size_t)n, sizeof *v, dcmp);
    printf("  %-34s median %8.4f  min %8.4f  max %8.4f %s (n=%d)\n", what, v[n / 2], v[0], v[n - 1],
           unit, n);
}

/* A snapshot whose lexicon has one extension lexical rule. */
static ParserSnapshot *with_rule(const char *pattern) {
    static const char *g = "%name GB\n%token_type { int }\n%token ID EXT.\ns ::= ID.\ns ::= EXT.\n";
    ParserSnapshot *s = NULL;
    if (lime_compile_grammar_in_process(g, strlen(g), &s, NULL) != 0 || !s) return NULL;
    GrammarModification m;
    memset(&m, 0, sizeof m);
    m.type = MOD_ADD_LEX_RULE;
    m.u.add_lex_rule.name = "ext";
    m.u.add_lex_rule.pattern = pattern;
    m.u.add_lex_rule.token = "EXT";
    char *e = lime_lex_compose(s, NULL, &m, 1);
    if (e) {
        printf("  compose: %s\n", e);
        free(e);
        snapshot_release(s);
        return NULL;
    }
    return s;
}

int main(int argc, char **argv) {
    /* cold: a lead byte absent from the corpus (\xA7 does not occur);
    ** hot: '#{...}' -- '#' occurs, '#{' does not, so every '#' runs the
    ** extension DFA one byte and declines. */
    ParserSnapshot *cs = with_rule("\\xa7\\{[^}]*\\}");
    ParserSnapshot *hs = with_rule("#\\{[^}]*\\}");
    if (!cs || !hs) return 1;
    const LimeLexicon *cold = lime_snapshot_lexicon(cs), *hot = lime_snapshot_lexicon(hs);

    char **bufs = calloc((size_t)argc, sizeof *bufs);
    size_t *lens = calloc((size_t)argc, sizeof *lens), bytes = 0;
    for (int a = 1; a < argc; a++) {
        bufs[a] = slurp(argv[a], &lens[a]);
        if (bufs[a]) bytes += lens[a];
    }
    unsigned long long h[NV];
    size_t nt[NV];
    for (int v = 0; v < NV; v++) {
        g_hash = 1469598103934665603ull;
        g_ntok = 0;
        run(v, cold, hot, bufs, lens, argc);
        h[v] = g_hash;
        nt[v] = g_ntok;
    }
    int bad = 0;
    for (int v = 1; v < NV; v++)
        if (h[v] != h[0] || nt[v] != nt[0]) {
            printf("  MISMATCH %s: %zu tokens hash %016llx vs plain %zu %016llx\n", vname[v], nt[v],
                   h[v], nt[0], h[0]);
            bad++;
        }
    printf("gate: %d files, %zu bytes, %zu tokens; all variants identical: %s\n", argc - 1, bytes,
           nt[0], bad ? "NO" : "yes");
    /* BENCH_ONLY=v: run just variant v, BENCH_LOOPS times (for perf stat) */
    if (getenv("BENCH_ONLY")) {
        int v = atoi(getenv("BENCH_ONLY")), loops = getenv("BENCH_LOOPS") ? atoi(getenv("BENCH_LOOPS")) : 20;
        for (int k = 0; k < loops; k++) run(v, cold, hot, bufs, lens, argc);
        printf("ran %s x%d\n", vname[v], loops);
    }
    int reps = getenv("BENCH_REPS") ? atoi(getenv("BENCH_REPS")) : 0;
    if (reps > 0 && !bad) {
        double *t[NV], *r[NV];
        for (int v = 0; v < NV; v++) {
            t[v] = malloc(sizeof(double) * (size_t)reps);
            r[v] = malloc(sizeof(double) * (size_t)reps);
        }
        for (int k = -2; k < reps; k++) {
            for (int w = 0; w < NV; w++) {
                int v = (w + (k < 0 ? 0 : k)) % NV;
                double t0 = cpu_ns();
                run(v, cold, hot, bufs, lens, argc);
                if (k >= 0) t[v][k] = (cpu_ns() - t0) / (double)bytes;
            }
            if (k >= 0)
                for (int v = 0; v < NV; v++) r[v][k] = t[v][k] / t[V_PLAIN][k];
        }
        printf("ns per input byte (CPU time), and ratio to plain in the same rep:\n");
        for (int v = 0; v < NV; v++) report(vname[v], t[v], reps, "ns/B");
        for (int v = 1; v < NV; v++) {
            char nm[64];
            snprintf(nm, sizeof nm, "ratio %s", vname[v]);
            report(nm, r[v], reps, "");
        }
        for (int v = 0; v < NV; v++) {
            free(t[v]);
            free(r[v]);
        }
    }
    for (int a = 0; a < argc; a++) free(bufs[a]);
    free(bufs);
    free(lens);
    snapshot_release(cs);
    snapshot_release(hs);
    return bad ? 1 : 0;
}
